  .ew-badge:not([data-variant]) { --ew-spec-variant-variant: count; }
  .ew-badge[data-size="sm"] { --ew-spec-size: sm; }
  .ew-badge[data-size="md"] { --ew-spec-size: md; }
  .ew-badge:not([data-size]) { --ew-spec-size: md; }
